#include <stdlib.h>
#include <string.h>
#include <omp.h>

#if defined(__AVX512F__)
#define VW 16
#define MR 12
#define MC 96    /* multiple of MR */
#define NCG 4    /* B panels per task */
#else
#define VW 8
#define MR 6
#define MC 72
#define NCG 6
#endif

#define NR (2 * VW)
#define KTARGET 512

typedef float vf __attribute__((vector_size(VW * 4)));

static inline void kernel(int kc, const float *restrict Ap, const float *restrict Bp,
                          float *restrict C, int ldc, int first, int mr, int nr)
{
    vf c[MR][2];
#pragma GCC unroll 16
    for (int r = 0; r < MR; r++) {
        c[r][0] = (vf){0}; c[r][1] = (vf){0};
        if (!first && r < mr) {
            __builtin_prefetch(C + (size_t)r * ldc, 1, 3);
            __builtin_prefetch(C + (size_t)r * ldc + NR - 1, 1, 3);
        }
    }

#pragma GCC unroll 4
    for (int k = 0; k < kc; k++) {
        vf b0 = *(const vf *)(Bp + k * NR);
        vf b1 = *(const vf *)(Bp + k * NR + VW);
        const float *a = Ap + k * MR;
#pragma GCC unroll 16
        for (int r = 0; r < MR; r++) {
            float av = a[r];
            c[r][0] += av * b0;
            c[r][1] += av * b1;
        }
    }

    if (mr == MR && nr == NR) {
#pragma GCC unroll 16
        for (int r = 0; r < MR; r++) {
            float *cr = C + (size_t)r * ldc;
            vf v0 = c[r][0], v1 = c[r][1];
            if (!first) {
                vf o0, o1;
                memcpy(&o0, cr, sizeof(vf));
                memcpy(&o1, cr + VW, sizeof(vf));
                v0 += o0; v1 += o1;
            }
            memcpy(cr, &v0, sizeof(vf));
            memcpy(cr + VW, &v1, sizeof(vf));
        }
    } else {
        float tmp[MR * NR] __attribute__((aligned(64)));
        for (int r = 0; r < MR; r++) {
            memcpy(tmp + r * NR, &c[r][0], sizeof(vf));
            memcpy(tmp + r * NR + VW, &c[r][1], sizeof(vf));
        }
        for (int r = 0; r < mr; r++) {
            float *cr = C + (size_t)r * ldc;
            const float *t = tmp + r * NR;
            int j = 0;
            if (nr >= VW) {
                vf v; memcpy(&v, t, sizeof(vf));
                if (!first) { vf o; memcpy(&o, cr, sizeof(vf)); v += o; }
                memcpy(cr, &v, sizeof(vf));
                j = VW;
            }
            if (first)
                for (; j < nr; j++) cr[j] = t[j];
            else
                for (; j < nr; j++) cr[j] += t[j];
        }
    }
}

static void *alloc_pages(size_t bytes)
{
    bytes = (bytes + 4095) & ~(size_t)4095;
    if (bytes == 0) bytes = 4096;
    return aligned_alloc(4096, bytes);
}

static float *sAp, *sBp;
static size_t sAcap, sBcap;

static float *grow(float **p, size_t *cap, size_t need)
{
    if (need > *cap) {
        free(*p);
        *p = (float *)alloc_pages(need * sizeof(float));
        *cap = need;
    }
    return *p;
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    int npan = (n + NR - 1) / NR;     /* B micro-panels */
    int nmp = (n + MR - 1) / MR;      /* A micro-panels */
    int nrb = (n + MC - 1) / MC;      /* row blocks */
    int ncg = (npan + NCG - 1) / NCG; /* column groups */
    int ntask = nrb * ncg;
    const int mpb = MC / MR;

    int nkb = (n + KTARGET - 1) / KTARGET;
    int KC = (n + nkb - 1) / nkb;

    float *Bp = grow(&sBp, &sBcap, (size_t)npan * NR * n + 16 * NR);
    float *Ap = grow(&sAp, &sAcap, (size_t)nmp * MR * n + 16 * MR);

    int nthreads = omp_get_max_threads();
    long work = (long)n * n * n;
    if (work < 64L * 64 * 64) nthreads = 1;

    #pragma omp parallel num_threads(nthreads) proc_bind(close)
    {
        /* Pack B: panel p holds columns [p*NR, p*NR+NR) as [k][NR] over full K. */
        #pragma omp for schedule(static) nowait
        for (int p = 0; p < npan; p++) {
            float *dst = Bp + (size_t)p * NR * n;
            int j0 = p * NR;
            int nr = n - j0 < NR ? n - j0 : NR;
            if (nr == NR) {
                for (int k = 0; k < n; k++) {
                    const float *src = B + (size_t)k * n + j0;
                    float *d = dst + (size_t)k * NR;
                    vf v0, v1;
                    memcpy(&v0, src, sizeof(vf));
                    memcpy(&v1, src + VW, sizeof(vf));
                    memcpy(d, &v0, sizeof(vf));
                    memcpy(d + VW, &v1, sizeof(vf));
                }
            } else {
                for (int k = 0; k < n; k++) {
                    const float *src = B + (size_t)k * n + j0;
                    float *d = dst + (size_t)k * NR;
                    int j = 0;
                    for (; j < nr; j++) d[j] = src[j];
                    for (; j < NR; j++) d[j] = 0.0f;
                }
            }
        }

        /* Pack A: micro-panel mp holds rows [mp*MR, mp*MR+MR) as [k][MR]. */
        #pragma omp for schedule(static)
        for (int mp = 0; mp < nmp; mp++) {
            float *d = Ap + (size_t)mp * MR * n;
            int r0 = mp * MR;
            int mr = n - r0 < MR ? n - r0 : MR;
            const float *src[MR];
            for (int r = 0; r < MR; r++)
                src[r] = A + (size_t)(r0 + (r < mr ? r : 0)) * n;
            if (mr == MR) {
                for (int k = 0; k < n; k++) {
#pragma GCC unroll 16
                    for (int r = 0; r < MR; r++) d[(size_t)k * MR + r] = src[r][k];
                }
            } else {
                for (int k = 0; k < n; k++)
                    for (int r = 0; r < MR; r++)
                        d[(size_t)k * MR + r] = r < mr ? src[r][k] : 0.0f;
            }
        }

        #pragma omp for schedule(dynamic, 1)
        for (int t = 0; t < ntask; t++) {
            int rb = t / ncg, cg = t % ncg;
            int mp0 = rb * mpb;
            int mp1 = mp0 + mpb < nmp ? mp0 + mpb : nmp;
            int p0 = cg * NCG;
            int p1 = p0 + NCG < npan ? p0 + NCG : npan;

            for (int kk = 0; kk < n; kk += KC) {
                int kc = n - kk < KC ? n - kk : KC;
                int first = (kk == 0);
                /* A micro-panel stays in L1; the task's B panels stay in L2. */
                for (int mp = mp0; mp < mp1; mp++) {
                    int r0 = mp * MR;
                    int mr = n - r0 < MR ? n - r0 : MR;
                    const float *ap = Ap + (size_t)mp * MR * n + (size_t)kk * MR;
                    for (int p = p0; p < p1; p++) {
                        int j0 = p * NR;
                        int nr = n - j0 < NR ? n - j0 : NR;
                        kernel(kc, ap, Bp + (size_t)p * NR * n + (size_t)kk * NR,
                               C + (size_t)r0 * n + j0, n, first, mr, nr);
                    }
                }
            }
        }
    }
}
